CREATE TABLE dbo.vectors
(
    id INT PRIMARY KEY,
    v VECTOR(3) NOT NULL
);

INSERT INTO dbo.vectors VALUES (1, '[0.1, 2, 30]'), (2, '[-100.2, 0.123, 9.876]');

DECLARE @qv VECTOR(3) = '[0.1, 2, 30]';
SELECT TOP (10) id, VECTOR_DISTANCE('cosine', @qv, v) AS distance
FROM dbo.vectors
ORDER BY distance;
